/* Get a random dad joke from icanhazdadjoke.com and display it */
const HOST = "icanhazdadjoke.com";
const USER_AGENT = "Espruino Badge dadjoke app (https://github.com/espruino/BadgeApps)";
const SEEN_FILE = "dadjoke.json";
const SEEN_MAX = 48; // one day of refreshes, so no joke repeats within a day
const REFRESH_MINS = 30;

var http = require("http");
var log = print;

/* Comic Neue Bold for the joke and an extra-bold version of it for dialog markers
   such as "Doctor:" (SIL OFL 1.1, https://github.com/crozynski/comicneue).
   1bpp, largest first; both weights share one line height and baseline. The
   bitmaps are kept uncompressed on purpose: the App Loader turns these atob()
   literals into strings that stay in flash, so the fonts use no RAM (the badge
   only has ~53kB for variables). */
const FONTS = [
  { h : 74, // 64px
    d : atob(""),
    w : atob("FxEVLicsKA0XFxgcDBoMHCUZICAeIiEdISENDiMeIyA2IycmKCYlLS4aHiQhNCopIywlIyIrIjYtJSUVJRUiIQ0hIh4hHxYjIhARHw8zIyEhIRobFSEbKB8dGxgOGCc="),
    bd : atob(""),
    bw : atob("GxUZMiswLBEbGxwgEB4QICkdJCQiJiUhJSUREiciJyQ6JysqLCopMTIeIiglOC4tJzApJyYvJjoxKSkZKRkmJRElJiIlIxonJhQVIxM3JyUlJR4fGSUfLCMhHxwSHCs=") },
  { h : 60, // 52px
    d : atob(""),
    w : atob("Ew4RJR8jIQsTExQXChUJFx4UGhoYHBsXGxsLDBwYHBosHSAfIB8eJSUVGB0bKiIhHSQeHBsjHCwlHh4RHhEbGwsaGxgbGhIcGw0OGQwpHBsbGxUWERsWIBkYFhQLFCA="),
    bd : atob(""),
    bw : atob("FhEUKCImJA4WFhcaDRgMGiEXHR0bHx4aHh4ODx8bHx0vICMiIyIhKCgYGyAeLSUkICchHx4mHy8oISEUIRQeHg4dHhseHRUfHhARHA8sHx4eHhgZFB4ZIxwbGRcOFyM=") },
  { h : 49, // 42px
    d : atob(""),
    w : atob("DwsOHhkdGgkPDxASCBEIEhgRFRUUFhYTFhYJCRcUFxUkFxoZGhkYHh4RFBgWIhsbFx0YFxYcFyQeGBgOGA4WFgkVFhQWFQ4XFgoLFAohFxYWFRESDhYSGhUTEhAJEBk="),
    bd : atob(""),
    bw : atob("EQ0QIBsfHAsRERIUChMKFBoTFxcWGBgVGBgLCxkWGRcmGRwbHBsaICATFhoYJB0dGR8aGRgeGSYgGhoQGhAYGAsXGBYYFxAZGAwNFgwjGRgYFxMUEBgUHBcVFBILEhs=") },
  { h : 40, // 34px
    d : atob(""),
    w : atob("DAkLGBQXFQcMDA0PBg4GDxMNEREQEhIPERIHCBIQEhEdExUUFRQUGBgOEBMRGxYWExgUExIXEh0YFBQLEwsSEgcREhASEQwTEggJEQgbEhISEQ4OCxIOFREQDw0HDRU="),
    bd : atob(""),
    bw : atob("DgsNGhYZFwkODg8RCBAIERUPExMSFBQRExQJChQSFBMfFRcWFxYWGhoQEhUTHRgYFRoWFRQZFB8aFhYNFQ0UFAkTFBIUEw4VFAoLEwodFBQUExAQDRQQFxMSEQ8JDxc=") }
];
/* Smiley from https://icanhazdadjoke.com/static/smile.svg, 2bpp BWYR */
let img_smile = {
  width : 200, height : 200, bpp : 2,
  buffer : atob("")
};

/* Layout: the smiley sits in a fixed right column, the joke gets the rest,
   centered */
const IMG_X = 576, IMG_Y = 140;
const TEXT = { x : 24, y : 16, w : 528, h : 448 };

function setFont(g, f, bold) {
  if (f.vector) return g.setFont("Vector:" + f.vector);
  return bold ? g.setFontCustom(f.bd, 32, f.bw, f.h) : g.setFontCustom(f.d, 32, f.w, f.h);
}

/* A dialog marker is one capitalized word ending in ':' ("Doctor:", "Q:",
   "Sgt.:"), at the start of a line or right after a sentence ends. */
function isMarker(w, prev) {
  if (prev && ".!?".indexOf(prev[prev.length - 1]) < 0) return false;
  if (w.length < 2 || w.length > 12 || w[w.length - 1] != ":") return false;
  let c = w.charCodeAt(0);
  if (c < 65 || c > 90) return false;
  for (let i = 1; i < w.length - 1; i++) {
    c = w.charCodeAt(i);
    if (!((c >= 97 && c <= 122) || (c >= 65 && c <= 90) || c == 46)) return false;
  }
  return true;
}

/* Split `text` into paragraphs of words, each `{ t : text, b : bold }` */
function tokenize(text) {
  return text.split("\n").map(para => {
    let words = para.split(" ").filter(w => w != "");
    return words.map((w, i) => ({ t : w, b : isMarker(w, words[i - 1]) }));
  });
}

/* Vector fonts have no bold weight, so bold words are drawn twice, 1px apart */
function wordWidth(g, f, word) {
  return setFont(g, f, word.b).stringWidth(word.t) + (word.b && f.vector ? 1 : 0);
}

function lineWidth(g, f, words, space) {
  let w = 0;
  words.forEach((word, i) => { w += (i ? space : 0) + wordWidth(g, f, word); });
  return w;
}

/* Word wrap paragraphs to `width` in font `f`. Words wider than a line are
   split. Returns lines as `{ words, w }`. */
function wrap(g, f, paras, width) {
  let lines = [];
  let space = setFont(g, f).stringWidth(" ");
  paras.forEach(words => {
    let line = [], lw = 0;
    words.forEach(word => {
      let ww = wordWidth(g, f, word);
      while (ww > width) {
        let n = word.t.length - 1;
        while (n > 1 && wordWidth(g, f, { t : word.t.substr(0, n), b : word.b }) > width) n--;
        if (line.length) { lines.push({ words : line, w : lw }); line = []; lw = 0; }
        let head = { t : word.t.substr(0, n), b : word.b };
        lines.push({ words : [head], w : wordWidth(g, f, head) });
        word = { t : word.t.substr(n), b : word.b };
        ww = wordWidth(g, f, word);
      }
      if (line.length && lw + space + ww > width) {
        lines.push({ words : line, w : lw });
        line = []; lw = 0;
      }
      lw += (line.length ? space : 0) + ww;
      line.push(word);
    });
    lines.push({ words : line, w : lw });
  });
  return lines;
}

/* Pick the largest font the whole joke fits in, falling back to ever smaller
   vector fonts. If even the smallest does not fit, cut the text and end it
   with "...", so it never leaves the text area. */
function layout(g, text) {
  let paras = tokenize(text);
  let candidates = FONTS.slice();
  for (let s = 32; s >= 12; s -= 2) candidates.push({ vector : s });
  let f, lines, lh;
  for (let i = 0; i < candidates.length; i++) {
    f = candidates[i];
    lh = setFont(g, f).getFontHeight();
    lines = wrap(g, f, paras, TEXT.w);
    if (lines.length * lh <= TEXT.h) break;
  }
  let maxLines = Math.floor(TEXT.h / lh);
  if (lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    let last = lines[maxLines - 1], space = setFont(g, f).stringWidth(" ");
    let more = { t : "...", b : false };
    while (last.words.length && lineWidth(g, f, last.words.concat([more]), space) > TEXT.w)
      last.words.pop();
    last.words.push(more);
    last.w = lineWidth(g, f, last.words, space);
  }
  return { font : f, lines : lines, lh : lh, space : setFont(g, f).stringWidth(" ") };
}

function draw(g, l) {
  g.setColor(0).setBgColor(1).clear();
  g.drawImage(img_smile, IMG_X, IMG_Y);
  g.setColor(0).setFont("Vector:18").setFontAlign(0, -1);
  g.drawString("icanhazdadjoke.com", IMG_X + img_smile.width / 2, IMG_Y + img_smile.height + 16);
  let y = TEXT.y + Math.floor((TEXT.h - l.lines.length * l.lh) / 2);
  l.lines.forEach((line, i) => {
    let x = TEXT.x + Math.floor((TEXT.w - line.w) / 2), ly = y + i * l.lh;
    line.words.forEach(word => {
      setFont(g, l.font, word.b).setFontAlign(-1, -1).drawString(word.t, x, ly);
      if (word.b && l.font.vector) g.drawString(word.t, x + 1, ly);
      x += wordWidth(g, l.font, word) + l.space;
    });
  });
}

/* The API escapes non-ASCII as \uXXXX. Map the common ones to ASCII in the
   raw JSON (so it works with or without Unicode support in the firmware), and
   drop any others since the font only covers ASCII. */
const ASCII = {
  "2018" : "'", "2019" : "'", "201c" : "\\\"", "201d" : "\\\"",
  "2013" : "-", "2014" : "-", "2026" : "...", "00a0" : " ", "00f1" : "n"
};
function parseJoke(raw) {
  let out = "", i = 0, j;
  while ((j = raw.indexOf("\\u", i)) >= 0) {
    out += raw.substring(i, j);
    let hex = raw.substr(j + 2, 4).toLowerCase();
    if (hex in ASCII) out += ASCII[hex];
    else if (parseInt(hex, 16) < 0x7F) out += raw.substr(j, 6);
    i = j + 6;
  }
  let json = JSON.parse(out + raw.substr(i));
  let text = "";
  for (i = 0; i < json.joke.length; i++) {
    let c = json.joke.charCodeAt(i);
    if (c == 10 || (c >= 32 && c < 127)) text += json.joke[i];
  }
  text = text.split("\n").map(s => s.trim()).filter(s => s != "").join("\n");
  return { id : json.id, text : text };
}

function httpGet() {
  log("Fetch https://" + HOST + "/");
  return new Promise((resolve, reject) => {
    var timeout = setTimeout(function() {
      reject("HTTP Timeout");
    }, 30000);
    let opts = {
      host : HOST, port : 443, path : "/", protocol : "https:",
      headers : { "Accept" : "application/json", "User-Agent" : USER_AGENT }
    };
    try {
      http.get(opts, function(res) {
        let d = "";
        res.on('data', function(data) { d += data; });
        res.on('close', function() {
          clearTimeout(timeout);
          log("Fetch success");
          resolve(d);
        });
      });
    } catch (e) {
      clearTimeout(timeout);
      reject(e);
    }
  });
}

/* Fetch a joke, retrying a couple of times if it was shown recently */
function getJoke(seen, tries) {
  return httpGet().then(data => {
    let joke = parseJoke(data);
    if (seen.includes(joke.id) && tries > 1) return getJoke(seen, tries - 1);
    return joke;
  });
}

/* Deep sleep until the timeout, or until either button is pressed. Waking on
   a timer and a button at once needs firmware 2v29.491 or later; older
   firmware only wakes on the timer. */
function canWakeOnButtons() {
  let v = process.env.VERSION.split("v"); // eg. "2v29.491"
  let major = +v[0], minor = parseInt(v[1]), build = +(v[1].split(".")[1] || 0);
  return major > 2 || (major == 2 && (minor > 29 || (minor == 29 && build >= 491)));
}
function sleep(mins) {
  Badge.setLEDs(); // off
  if (canWakeOnButtons()) {
    ESP32.deepSleep({ timeout : mins * 60 * 1000, ext1 : [BTN1, BTN2], ext1Level : false });
  } else {
    ESP32.deepSleep(mins * 60 * 1000000);
  }
}

function showJoke() {
  Badge.setLEDs("#110"); // dim yellow while we fetch and render
  let seen = require("Storage").readJSON(SEEN_FILE, 1) || [];
  Badge.connectWiFi().then(function() {
    return getJoke(seen, 3);
  }).then(joke => {
    log(joke.text);
    seen = seen.filter(id => id != joke.id).concat([joke.id]).slice(-SEEN_MAX);
    require("Storage").writeJSON(SEEN_FILE, seen);
    let l = layout(Graphics.createArrayBuffer(8, 8, 1), joke.text);
    return Badge.showRendering(function(g) { draw(g, l); });
  }).then(() => {
    sleep(REFRESH_MINS);
  }).catch(e => {
    Badge.showError(e).then(() => {
      sleep(5); // try again in 5 mins
    });
  });
}

/* Holding either button for 1.5s at wakeup keeps the badge awake (LEDs blue)
   so you can connect over USB or Bluetooth. Pressing a button again then
   fetches a new joke. A short press just fetches a new joke straight away. */
let pressStart = getTime();
let pressCheck = setInterval(function() {
  if (!BTN1.read() && !BTN2.read()) {
    clearInterval(pressCheck);
    showJoke();
  } else if (getTime() - pressStart > 1.5) {
    clearInterval(pressCheck);
    log("Staying awake for connection");
    Badge.setLEDs("#007");
    let next = () => { clearWatch(); showJoke(); };
    setWatch(next, BTN1, { edge : "rising", debounce : 50 });
    setWatch(next, BTN2, { edge : "rising", debounce : 50 });
  }
}, 50);
